	if (range == 1) {
		return 0;
	}

	/* Compute the ceiling of lg(range). */
	unsigned lg_range = ffs_u32(pow2_ceil_u32(range));

	/* Generate a result in [0..range) via repeated trial. */
	uint32_t ret;
	do {
		ret = prng_lg_range_u32(state, lg_range);
	} while (ret >= range);

	return ret;
}

